use std::{cell::Cell, future::Future, task::{Context, Poll, Waker}};
let saved = Cell::new(false);
let acked = Cell::new(false);
let mut op = Box::pin(async {
    saved.set(true);
    std::future::pending::<()>().await;
    acked.set(true);
});
let mut cx = Context::from_waker(Waker::noop());
let _ = op.as_mut().poll(&mut cx);
drop(op);
println!("saved={} acked={}", saved.get(), acked.get());
